      "s.k.longPressHint": "Halten Sie die Taste auf dem Telefon für eine halbe Sekunde gedrückt, um diese andere Taste stattdessen auszuführen.Speichern Sie zuerst einen neuen Schlüssel, um ihn hier auszuwählen.",
      "s.k.cycle": "Durch andere Tasten wechseln",
