      "s.claude.notInstalled": "Nicht installiert",
      "s.adv.latestRelease": "Neueste Version",
      "s.adv.lastCheck": "Letzte Kontrolle",
      "s.adv.notYet": "Noch nicht verfügbar",
      "s.cal.hint": "Für die Kinder <b>Agenda</b> Fügen Sie eine iCalendar-Adresse (ICS) ein: Google Kalender › Einstellungen › Ihren Kalender › <i>Geheime Adresse im iCal-Format</i>Outlook › Einstellungen › Kalender › Freigegebene Kalender › <i>Einen Kalender veröffentlichen</i> (ICS-Link); iCloud › als öffentlichen Kalender freigeben (<code>webcal://</code> Die Adressen bleiben auf diesem Computer.",
      "s.ha.tokenHint": "Für die Kinder <b>Home Assistant</b> Erstellen Sie ein Token in Ihrem Konto. Home Assistant › Ihr Profil › Sicherheit › <i>Langlebige Zugangstokens</i>. Das Token bleibt auf diesem Computer; das Telefon sieht nur die Entitäten in seiner Widgets-Liste.Home Assistant Sie können auch Werte und Benachrichtigungen in das Panel pushen, siehe Webhooks.)",
      "s.battery.leadTail": "Woher es kommt: ein <b> smart plug in Home Assistant </b> (das Telefon auf eigenem Ladegerät), oder zwei <b> shortcuts </b> , zum Beispiel <code>uhubctl</code> für einen USB hub mit schaltbaren ports.Ohne USB power läuft das Panel weiter über Wi-Fi .",
      "s.claude.hint": "Wenn Claude Code um Erlaubnis bittet (Befehl ausführen, Datei bearbeiten…) zeigt das Telefon die Anfrage mit <b> Allow </b> und <b> Deny </b> an. Ist das Telefon nicht verbunden oder niemand antwortet rechtzeitig, fragt Claude Code wie üblich im Terminal nach, was einen kleinen Hook in <code>~/.claude/settings.json</code> erfordert; PhoneBox fügt ihn für Sie hinzu (ein Backup wird neben der Datei aufbewahrt).",
      "s.wifi.lead": "Koppeln Sie ein Telefon, indem Sie es einmal anschließen USB Nach dem Einschalten (und Neustart) oder ohne Kabel: <b>Ein Telefon koppeln Wi-Fi</b> zeigt ein QR Das Telefon spricht dann HTTPS mit diesem PC, vertraut nur dem Zertifikat dieses PCs und muss einen geheimen Schlüssel vorlegen.Das Telefon und dieser PC müssen sich im selben Netzwerk befinden &mdash; oder beide auf einem gemeinsamen Netzwerk <a href=\"https://tailscale.com\" target=\"_blank\" rel=\"noopener\">Tailscale</a>, die auch von einem anderen Ort oder über separate Wi-Fi Netzwerke. Windows Firewall fragt einmal &mdash; erlauben Sie es (Kreuzen Sie den Netzwerktyp Tailscale Auch für die Verwendung).",
      "s.upd.checksBefore": "Checks",
      "s.upd.checksAfter": "on GitHub Die Telefon-App wird über die App Store-Website installiert. USB Der Agent ersetzt seine eigenen Dateien und startet neu.",
      "s.wh.payloadHint": "JSON Nutzlasten können tragen",
      "s.k.argsPlaceholderWindows": "z.B. -d D:\\Projekte claude",
      "s.k.argsPlaceholderUnix": "z.B. --new-window ~/Projekte",
