      "s.ap.inheritFont": "Inherit ( {font} )",
      "s.battery.leadHead": "Ein Telefon, das ständig angeschlossen ist, verschleißt den Akku.PhoneBox kann es zwischen zwei Ladevorgängen halten.",
      "s.battery.leadMid": "Telefone können das Laden nicht ohne Root selbst stoppen, so dass die Stromversorgung durch einen Schalter auf dem Gerät eingestellt wird.",
      "s.wh.payloadHintFull": "JSON Nutzlasten können tragen <code>value</code>, <code>title</code>, <code>sub</code>, <code>unit</code>, <code>icon</code>, <code>color</code>, <code>level</code> (ok / warn / error), <code>progress</code> (0&ndash;1 oder 0&ndash,100), <code>items</code> (eine Liste) und <code>ttl</code> (Sekunden). Klartext oder eine Zahl funktionieren auch. Benachrichtigungen dauern <code>title</code>, <code>text</code>, <code>level</code>, <code>vibrate</code>, <code>seconds</code>, <code>wake</code> (beleuchten Sie den Nachtbildschirm) und <code>page</code> (Wechseln Sie zu ihm).",
      "s.pair.title": "Ein Telefon mit {pc} koppeln",
