      "s.k.macroHint": "keys:… appuie sur les touches, text:… tape, wait:300 attend (millisecondes), shortcut:id exécute un autre raccourci. if:running:spotify … else … endif exécute les étapes entre les deux seulement si la condition est remplie (running:program, muted, on:shortcut-id, push:key; ! in front le retourne). clipboard:… met du texte dans le presse-papiers, paste:… colle du texte à travers celui-ci et remet ce qui a été copié. {clipboard} dans une étape de texte, presse-papiers ou collage est remplacé par ce qui se trouve dans le presse-papier.",
      "s.k.textHint": "{clipboard} est remplacé par le texte du presse-papiers (les 10 000 premiers caractères).",
      "s.k.clipboardWarn": "Le texte saisi passe par l'outil de saisie du système, donc sur un Mac ou Linux, un mot de passe copié peut apparaître dans la liste des processus pendant qu'il est tapé. En saisissant {clipboard} dans un terminal, tout ce qui a été copié y est exécuté. coller: garde son texte hors de l'historique du presse-papiers Windows et du presse-papier cloud et remet ensuite le texte copié (une image ou des fichiers copiés ne sont pas conservés: le presse-papier est laissé vide); sur un Mac, Universal Clipboard peut toujours le synchroniser avec vos autres périphériques.",
      "s.k.macosPermission": "macOS demande une fois d'autoriser PhoneBoxAgent dans Préférences Système › Confidentialité et sécurité › Accessibilité.",
