      "s.k.longPressHint": "Maintenez la touche sur le téléphone pendant une demi-seconde pour exécuter cette autre touche à la place.Enregistrez d'abord une nouvelle clé pour la choisir ici.",
      "s.k.cycle": "Parcourir d'autres touches",
      "s.k.cycleKeys": "Touches, une par robinet",
      "s.k.cycleAdd": "Ajouter une clé",
      "s.k.cycleHint": "Chaque pression exécute la touche suivante de la liste, puis recommence à partir de la première. La touche sur le téléphone affiche celle qui a été lancée en dernier (son icône et son nom). Avant la première pression, elle affiche sa propre touche.",
      "s.k.cycleFew": "Si une seule clé est dans la liste, cette clé exécute simplement cette clé. Si aucune n'est présente, elle ne fait rien. Les clés qui n'existent plus sont supprimées de la liste lorsque vous sauvegardez.",
      "s.appearance.originalWidgetFont": "Police de widget originale",
