      "s.adv.notYet": "Pas encore",
      "s.cal.hint": "Pour le <b>Ordre du jour</b> Coller une adresse iCalendar (ICS) : Google Agenda › Paramètres › votre calendrier › Ajouter un calendrier à Google Calendar <i>Adresse secrète au format iCal</i>Outlook › Paramètres › Calendrier › Calendriers partagés › <i>Publier un calendrier</i> (lien ICS) ; iCloud › partager en tant que calendrier public (lien<code>webcal://</code> Les adresses restent sur cet ordinateur.",
      "s.ha.tokenHint": "Pour le widget <b> Home Assistant </b>. Créer un token dans Home Assistant › votre profil › Sécurité › <i> Tokens d'accès à long terme </i> . Le token reste sur cet ordinateur, le téléphone ne voit que les entités de sa liste de widgets. (Home Assistant peut également pousser des valeurs et notifications vers le panneau, voir Webhooks.)",
      "s.battery.leadTail": "où il vient de: un <b> smart plug dans Home Assistant </b> (le téléphone sur son propre chargeur), ou deux <b> raccourcis </b> , par exemple <code>uhubctl</code> pour un hub USB avec des ports commutables.Sans l'alimentation USB le panneau continue à fonctionner sur Wi-Fi .",
      "s.claude.hint": "Lorsque Claude Code demande une autorisation (exécuter une commande, modifier un fichier…), le téléphone affiche la requête avec <b> Allow </b> et <b> Deny </b> . Si le téléphone n'est pas connecté ou que personne ne répond à temps, Claude Code demande dans le terminal comme d'habitude, ce qui nécessite un petit hook dans <code>~/.claude/settings.json</code> ; PhoneBox l'ajoute pour vous (une sauvegarde est conservée à côté du fichier).",
      "s.wifi.lead": "Couplez un téléphone en le branchant une fois USB après avoir allumé ce bouton (et redémarré), ou sans câble: <b>Coupler un téléphone Wi-Fi</b> montre un QR Le téléphone communique ensuite en HTTPS avec ce PC, fait confiance uniquement au certificat de ce PC et doit présenter une clé secrète. Le téléphone et le PC doivent être sur le même réseau &mdash; ou les deux sur le même réseau <a href=\"https://tailscale.com\" target=\"_blank\" rel=\"noopener\">Tailscale</a>, qui fonctionne également à partir d'un autre endroit ou sur des Wi-Fi réseaux. Windows Le pare-feu demande une fois &mdash; l'autoriser (cochez le type de réseau Tailscale Utilisations, aussi).",
      "s.upd.checksBefore": "Vérifications",
      "s.upd.checksAfter": "on GitHub L'application téléphonique est installée sur le téléphone. USB sans invite sur le téléphone; l'agent remplace ses propres fichiers et redémarre.",
      "s.wh.payloadHint": "JSON charges utiles peuvent transporter",
      "s.k.argsPlaceholderWindows": "e.g. -d D:\\Projets claude",
      "s.k.argsPlaceholderUnix": "Par exemple --new-window ~/Projets",
