      "s.pageSwitch.lead": "Cómo las reglas, los webhooks y el retorno inactivo cambian la página. En lugar de saltar, el teléfono muestra “Claude me necesita — cambiando a AI en 3…” con Stay and Go ahora, luego se desvanece. Nunca saca una página mientras está usando el panel, y las reglas que se activan una tras otra esperan su turno en lugar de rebotar la pantalla hacia adelante y hacia atrás.",
