      "s.wh.lanHint": "Desde otras máquinas en su red o Tailscale , con la clave webhook (HTTPS con el certificado autofirmado de esta PC, por lo que curl necesita -k). La clave también puede ir en?token= para remitentes que no pueden establecer cabeceras. Solo abre los puntos finales del webhook, nunca la API del teléfono; reemplácelo si tiene fugas.",
