      "s.k.macroHint": "keys:… pulsa teclas, text:… escribe, wait:300 esperas (milisegundos), shortcut:id ejecuta otro atajo. if:running:spotify … else … endif ejecuta los pasos intermedios solo cuando la condición se cumple (running:program, muted, on:shortcut-id, push:key; ! in front lo da vuelta). clipboard:… pone texto en el portapapeles, paste:… pega texto a través de él y vuelve a poner lo que fue copiado. {clipboard} en un paso de texto, portapapeles o pegar es reemplazado por lo que está en el portapapele.",
      "s.k.textHint": "{clipboard} se reemplaza por el texto del portapapeles (los primeros 10.000 caracteres).",
      "s.k.clipboardWarn": "El texto escrito pasa por la herramienta de escritura del sistema, así que en un Mac o Linux una contraseña copiada puede aparecer en la lista de procesos mientras se escribe. Escribir {clipboard} en una terminal ejecuta lo que fue copiado allí. pegar: mantiene su texto fuera del historial del portapapeles Windows y el portapapeles de la nube y después vuelve a poner el texto que se copió (una imagen o archivos copiados no se conservan: el portapapeles queda vacío); en un Mac, Universal Clipboard todavía puede sincronizarlo con sus otros dispositivos.",
