      "s.kiosk.openOnConnect": "Abrir PhoneBox cuando el teléfono está conectado: activa el teléfono y lleva el panel al frente cada vez que se conecte a través de USB (apagar para abrirlo usted mismo, para un teléfono que también usas para probar aplicaciones)",
      "s.kiosk.followLock": "Siga el bloqueo de la computadora: apague la pantalla del teléfono cuando macOS se bloquee; despierten y abran PhoneBox cuando macOS se desbloquee (se requiere ADB; desbloquear manualmente los teléfonos protegidos por un PIN o contraseña)",
