      "s.wh.lanHint": "Da altre macchine sulla rete o Tailscale , con la chiave webhook (HTTPS con il certificato autofirmato di questo PC, quindi curl ha bisogno di -k). La chiave può anche andare in?token= per i mittenti che non possono impostare le intestazioni. Apre solo gli endpoint del webhook, mai l'API del telefono; sostituirlo se perde.",
