      "s.k.macroHint": "keys:… preme i tasti, text:… digita, wait:300 attese (millisecondi), shortcut:id esegue un’altra scorciatoia. if:running:spotify … else … endif esegue i passaggi intermedi solo quando la condizione è valida (running:program, muted, on:shortcut-id, push:key; ! in front lo capovolge). clipboard:… mette il testo negli appunti, paste:… incolla il testo attraverso di esso e rimette quello che è stato copiato. {clipboard} in un passo testo, appunti o incolla viene sostituito da ciò che si trova negli appunti.",
      "s.k.textHint": "{clipboard} viene sostituito dal testo negli Appunti (i primi 10.000 caratteri).",
      "s.k.clipboardWarn": "Il testo digitato passa attraverso lo strumento di digitazione del sistema, quindi su un Mac o Linux una password copiata può essere visualizzata nell'elenco dei processi mentre viene digitata. Digitando {clipboard} in un terminale si esegue tutto ciò che è stato copiato lì. incolla: mantiene il suo testo fuori dalla cronologia degli appunti Windows e dagli appunti cloud e successivamente rimette il testo che è stato copiata (un'immagine o file copiati non vengono conservati: gli appunti sono lasciati vuoti); su un Mac, Universal Clipboard potrebbe ancora sincronizzarlo con gli altri dispositivi.",
