      "s.cal.hint": "Per il ristorante <b>Ordine del giorno</b> Incollare un indirizzo iCalendar (ICS): Google Calendar › Impostazioni › il tuo calendario › <i>Indirizzo segreto in formato iCal</i>Outlook › Impostazioni › Calendario › Calendari condivisi › <i>Pubblicare un calendario</i> (collegamento ICS); iCloud › condividere come calendario pubblico (collegamento<code>webcal://</code> Gli indirizzi rimangono su questo computer.",
      "s.ha.tokenHint": "Per il ristorante <b>Home Assistant</b> Crea un token in questo widget. Home Assistant › il tuo profilo › Sicurezza › <i>Token di accesso a lunga durata</i>Il token rimane su questo computer; il telefono vede solo le entità che sono nella sua lista di widget.Home Assistant È anche possibile inviare valori e notifiche al pannello, vedere Webhooks.)",
      "s.battery.leadTail": "Da dove proviene: una smart plug <b> in Home Assistant </b> (il telefono sul proprio caricabatterie), o due scorciatoie <b> </b>, ad esempio <code>uhubctl</code> per un hub USB con porte switchable.Senza alimentazione USB il pannello continua a funzionare su Wi-Fi .",
      "s.claude.hint": "Quando Claude Code chiede il permesso (eseguire un comando, modificare un file…), il telefono mostra la richiesta con <b> Allow </b> e <b> Deny </b> . Se il telefono non è collegato o nessuno risponde in tempo, Claude Code chiedere nel terminale come al solito. Questo ha bisogno di un piccolo hook in <code>~/.claude/settings.json</code> ; PhoneBox lo aggiunge per voi (un backup viene mantenuto accanto al file).",
      "s.wifi.lead": "Associare un telefono collegandolo una volta sopra USB dopo aver acceso questo (e riavviato), o senza un cavo: <b>Associare un telefono Wi-Fi</b> mostra un QR Il telefono quindi comunica HTTPS con questo PC, si fida solo del certificato di questo PC e deve presentare una chiave segreta. Il telefono e il PC devono essere sulla stessa rete &mdash; o entrambi su un'unica rete Wi-Fi. <a href=\"https://tailscale.com\" target=\"_blank\" rel=\"noopener\">Tailscale</a>, che funziona anche da un altro luogo o attraverso separati Wi-Fi Le reti. Windows Il firewall chiede una volta &mdash; consentirlo (selezionare il tipo di rete Tailscale Anche per altri usi).",
      "s.upd.checksBefore": "Controlli",
      "s.upd.checksAfter": "su GitHub L'app per il telefono è installata su un dispositivo mobile. USB senza una richiesta sul telefono; l'agente sostituisce i propri file e si riavvia.",
      "s.wh.payloadHint": "I carichi utili JSON possono trasportare",
