      "s.wh.lanHint": "De outras máquinas na sua rede ou Tailscale , com a chave webhook (HTTPS com certificado auto-assinado deste PC, por isso o curl precisa de -k). A chave também pode entrar em?token= para remetentes que não podem definir cabeçalhos. Apenas abre os pontos finais do webhook, nunca a API do telefone; substitua se tiver vazamentos.",
