      "s.wifi.step2Hint": "Abra o link que ele mostra e escolha PhoneBox. O telefone pede para confirmar o código . ",
      "s.wifi.noCableHint": "Não há cabo USB, opções de desenvolvedor ou adb necessário.O telefone e este computador deve estar na mesma rede (ou ambos em Tailscale).",
