      "s.kiosk.homeScreen": "Use o painel como tela inicial do telefone: ele começa após uma reinicialização e Home retorna a ele (desligue para obter seu lançador de volta)",
      "s.kiosk.keepAwake": "Mantenha o telefone acordado: desligue o protetor de tela do Android (ele começa no carregador) e mantenha a tela ligada enquanto estiver conectado (definido sobre o USB)",
      "s.kiosk.openOnConnect": "Abra o PhoneBox quando o telefone estiver conectado: acorde o telefone e traga o painel para a frente sempre que ele se conectar ao USB (desligue para abrir você mesmo, para um telefone que você também usa para testes de aplicativos)",
      "s.kiosk.followLock": "Siga o bloqueio do computador: desligue a tela do telefone quando o macOS bloquear; acorde e abra PhoneBox quando o macOS desbloquear (ADB necessário; desbloqueie telefones protegidos por um PIN ou senha manualmente)",
