      "s.ap.inheritFont": "Herdar ( {font} )",
      "s.battery.leadHead": "Um telefone que está conectado o tempo todo desgasta sua bateria.PhoneBox pode mantê-lo entre dois",
      "s.battery.leadMid": "Os telefones não podem parar de carregar por si só sem root, então o poder é ligado e desligado automaticamente.",
      "s.wh.payloadHintFull": "JSON cargas úteis podem transportar <code>value</code>, <code>title</code>, <code>sub</code>, <code>unit</code>, <code>icon</code>, <code>color</code>, <code>level</code> (ok / aviso / erro), <code>progress</code> (0&ndash;1 ou 0&ndash,100), <code>items</code> (uma lista) e <code>ttl</code> (segundos). Texto simples ou um número também funciona. Notificações levam <code>title</code>, <code>text</code>, <code>level</code>, <code>vibrate</code>, <code>seconds</code>, <code>wake</code> (iluminar a tela da noite) e <code>page</code> (mude para ele).",
      "s.pair.title": "Emparelhar um telefone com {pc}",
