      "A live picture from an IP camera (RTSP), 5 frames a second by default (1 to 10). Add the camera in Settings › General › Cameras; the computer pulls it with ffmpeg, and its address stays there.": "Uma imagem ao vivo de uma câmera IP (RTSP), 5 quadros por segundo por padrão (1 a 10).Adicione a câmera em Configurações › Geral › Câmeras; o computador puxa-lo com ffmpeg, e seu endereço permanece lá.",
      "A picture or webcam snapshot from a URL, optionally refreshed.": "Uma imagem ou instantâneo da webcam de um URL, opcionalmente atualizado.",
