      "s.k.macroHint": "keys:… drukt op toetsen, text:… typt, wait:300 wacht (milliseconden), shortcut:id voert een andere snelkoppeling uit. if:running:spotify … else … endif voert de tussenliggende stappen alleen uit als de voorwaarde waar is (running:program, muted, on:shortcut-id, push:key; ! in front draait het om). clipboard:… plaatst tekst op het klembord, plakken:… plakt tekst doorheen en zet wat gekopieerd werd terug. {clipboard} in een tekst-, klembord- of plakstap wordt vervangen door wat er op het klembord staat.",
      "s.k.textHint": "{clipboard} wordt vervangen door de tekst op het klembord (de eerste 10.000 tekens).",
      "s.k.clipboardWarn": "Getypte tekst gaat door de typtool van het systeem, dus op een Mac of Linux kan een gekopieerd wachtwoord in de proceslijst verschijnen terwijl het wordt getypt. Het typen van {clipboard} in een terminal voert alles uit wat daar is gekopieerd. plakken: houdt zijn tekst buiten de geschiedenis van het klembord en het cloudklembord van Windows en plaatst vervolgens de gekopieerde tekst terug (een gekopieerde afbeelding of bestanden worden niet bewaard: het klembord wordt leeg gelaten); op een Mac kan Universal Clipboard deze nog steeds synchroniseren met uw andere apparaten.",
