      "s.battery.leadHead": "Een telefoon die de hele tijd is aangesloten, slijpt zijn batterij uit. PhoneBox Kan het tussen twee houden",
      "s.battery.leadMid": "Telefoons kunnen niet stoppen met opladen door zichzelf zonder root, dus de macht wordt geschakeld om te voorkomen dat het apparaat leeg raakt.",
      "s.wh.payloadHintFull": "JSON Nuttige ladingen kunnen dragen <code>value</code>, <code>title</code>, <code>sub</code>, <code>unit</code>, <code>icon</code>, <code>color</code>, <code>level</code> (ok / waarschuwen / fout), <code>progress</code> (0&ndash;1 of 0&ndash,100), <code>items</code> (een lijst) en <code>ttl</code> (seconden). Tekst of een getal is ook mogelijk. Meldingen nemen <code>title</code>, <code>text</code>, <code>level</code>, <code>vibrate</code>, <code>seconds</code>, <code>wake</code> (licht het nachtscherm op) en <code>page</code> (schakel ernaar over).",
