      "s.adv.notYet": "Nie jeszcze",
      "s.cal.hint": "Dla dzieci <b>Agenda</b> Wklej adres iCalendar (ICS): Kalendarz Google › Ustawienia › Twój kalendarz › Wybierz pozycję Widok kalendarza. <i>Tajny adres w formacie iCal</i>; Outlook › Ustawienia › Kalendarz › Kalendarze udostępnione › <i>Publikowanie kalendarza</i> (link ICS); iCloud › udostępnianie jako kalendarz publiczny (link ICS)<code>webcal://</code> Adresy pozostają na tym komputerze.",
      "s.ha.tokenHint": "Dla dzieci <b>Home Assistant</b> Utwórz token w widżecie. Home Assistant › Twój profil › Bezpieczeństwo › <i>Tokeny dostępu długoterminowego</i>Token pozostaje na tym komputerze; telefon widzi tylko podmioty znajdujące się na jego liście widżetów. (Home Assistant Możesz również przesyłać wartości i powiadomienia do panelu, zobacz Webhooks.)",
      "s.battery.leadTail": "gdzie pochodzi: smart plug <b> w Home Assistant </b> (telefon na własnej ładowarce), lub dwa skróty <b> </b>, np. <code>uhubctl</code> dla hubów USB z przełączalnymi portami. Bez zasilania USB panel działa przez Wi-Fi. Wszystkie panele są podłączone do sieci bezprzewodowej.",
      "s.claude.hint": "Kiedy Claude Code prosi o pozwolenie (na uruchomienie polecenia, edycję pliku…) telefon wyświetla żądanie z <b> Allow </b> i <b> Deny </b> . Jeśli telefon nie jest podłączony lub nikt nie odpowiada na czas, Claude Code zapyta w terminalu jak zwykle, potrzebuje małego haka w <code>~/.claude/settings.json</code>; PhoneBox dodaje go dla Ciebie (kopia zapasowa jest przechowywana obok pliku).",
      "s.wifi.lead": "Sparuj telefon, podłączając go raz za razem USB Po włączeniu tego (i ponownym uruchomieniu) lub bez kabla: <b>Połącz telefon z komputerem Wi-Fi</b> Pokazuje a QR Telefon wtedy komunikuje się z tym komputerem za pomocą protokołu HTTPS, ufa tylko certyfikatowi tego komputera i musi przedstawić tajny klucz. Telefon i ten komputer muszą być podłączone do tej samej sieci lub oba muszą być podpięte do jednego portu USB. <a href=\"https://tailscale.com\" target=\"_blank\" rel=\"noopener\">Tailscale</a>, który działa również z innego miejsca lub przez oddzielne Wi-Fi Sieci. Windows Zapora pyta raz &mdash; pozwól na to (zaznacz typ sieci Tailscale Używa się też).",
      "s.upd.checksBefore": "Czeki",
      "s.upd.checksAfter": "on GitHub Aplikacja jest instalowana na telefonie przez 30 minut. USB Agent zastępuje własne pliki i uruchamia się ponownie.",
      "s.wh.payloadHint": "Ładunki JSON mogą przenosić",
      "s.k.argsPlaceholderWindows": "np. -d D:\\Projekty claude",
      "s.k.argsPlaceholderUnix": "np. --new-window ~/Projekty",
