      "s.ap.inheritFont": "Dziedziczenie ( {font} )",
      "s.battery.leadHead": "Telefon, który jest podłączony przez cały czas zużywa baterię. PhoneBox może utrzymać go między dwoma ładowarkami. 129,00 zł",
      "s.battery.leadMid": "Telefony nie mogą przestać ładować się same bez roota, więc zasilanie jest wyłączone, gdy telefon jest w trybie ładowania.",
      "s.wh.payloadHintFull": "JSON Ładunki mogą przenosić <code>value</code>, <code>title</code>, <code>sub</code>, <code>unit</code>, <code>icon</code>, <code>color</code>, <code>level</code> (ok / warn / error), <code>progress</code> (0 lub 1), <code>items</code> (lista) oraz <code>ttl</code> (sekund). Działa również zwykły tekst lub liczba. Powiadomienia trwają <code>title</code>, <code>text</code>, <code>level</code>, <code>vibrate</code>, <code>seconds</code>, <code>wake</code> (rozświetl nocny ekran) i <code>page</code> (przełącz się na niego).",
      "s.pair.title": "Sparowanie telefonu z {pc}",
