      "s.k.macroHint": "keys:… нажимает клавиши, text:… типы, wait:300 ожидания (миллисекунды), shortcut:id запускает другой ярлык. if:running:spotify … else … endif выполняет шаги между только когда условие сохраняется (running:program, muted, on:shortcut-id, push:key; ! впереди переворачивает его). clipboard:… ставит текст в буфер обмена, paste:… вставляет текст через него и возвращает то, что было скопировано. {clipboard} в тексте, буфера обмена или вставить шаг заменяется тем, что находится в буфере обмена.",
