      "s.k.clipboardWarn": "Введенный текст проходит через системный инструмент ввода, так что на Mac или Linux скопированный пароль может появляться в списке процессов во время его ввода. Ввод {clipboard} в терминал запускает то, что было скопировано там. paste: сохраняет свой текст из истории буфера обмена Windows и буфера обменов облака, а затем возвращает копированный текст (скопированное изображение или файлы не хранятся: буфер обмена остается пустым); на Mac Universal Clipboard все еще может синхронизировать его с другими устройствами.",
