      "s.adv.notYet": "Еще нет",
      "s.cal.hint": "Для <b> Agenda </b> widget и календарных правил. Вставьте iCalendar (ICS) адрес: Google Календарь › Настройки › ваш календарь › <i> Секретный адрес в формате iCal </i> ; Outlook › Настройки› Календарь › Общие календари › <i> Публикация календаря </i> (ICS ссылка); iCloud › поделиться как публичный календарь ( <code>webcal://</code> работает). Адреса остаются на этом компьютере.",
      "s.ha.tokenHint": "Для виджета <b> Home Assistant </b>. Создать токен в Home Assistant › ваш профиль › Безопасность › <i> Долговечные токены доступа </i> . Токен остается на этом компьютере; телефон только видит субъекты его список виджетов. ( Home Assistant также может отдавать значения и уведомления панели, см Webhooks.)",
      "s.battery.leadTail": "где он приходит от: <b> умный разъем в Home Assistant </b> (телефон на своем зарядном устройстве), или два <b> ярлыки </b> , например, <code>uhubctl</code> для концентратора USB с переключаемыми портами. Без USB власти панели продолжает работать над Wi-Fi .",
      "s.claude.hint": "Когда Claude Code просит разрешения (запуск команды, редактировать файл…), телефон показывает запрос с <b> Разрешить </b> и <b> Отказать </b> . Если телефон не подключен или никто не отвечает вовремя, Claude Code спрашивает в терминале как обычно. Это требует небольшой крючок в <code>~/.claude/settings.json</code> ; PhoneBox добавляет его для вас (резервная копия хранится рядом с файлом).",
      "s.wifi.lead": "Пары телефона, подключив его в один раз USB после включения этого (и перезагрузка), или без кабеля: <b>Пары телефона через Wi-Fi</b> показывает a QR код для сканирования с камерой телефона. Телефон затем говорит HTTPS к этому компьютеру, доверяет только сертификат этого компьютера и должен представить секретный ключ. Телефон и этот компьютер должны быть в одной сети &mdash; или оба на <a href=\"https://tailscale.com\" target=\"_blank\" rel=\"noopener\">Tailscale</a>, который также работает из другого места или через отдельные Wi-Fi сети. Windows Брандмауэр спрашивает один раз &mdash; разрешить (отметить тип сети Tailscale использует, тоже).",
      "s.upd.checksBefore": "Чеки",
      "s.upd.checksAfter": "на GitHub каждые 6 часов. Приложение для телефона устанавливается через USB без подсказки на телефоне; агент заменяет свои собственные файлы и перезапускает.",
      "s.wh.payloadHint": "Полезные нагрузки JSON могут перевозить",
      "s.k.argsPlaceholderWindows": "например -d D:\\Проекты claude",
      "s.k.argsPlaceholderUnix": "например --new-window ~/Проекты",
