      "s.ha.tokenHint": "对于 <b> Home Assistant </b> Widget,在 Home Assistant 中创建令牌 › your profile › Security › <i> 长期存储访问令牌 </i> 。 令牌保留在此计算机上;手机只能看到其 Widgets 列表中的实体。 (Home Assistant 也可以将值和通知推送到面板,请参阅 Webhook ) 。",
      "s.battery.leadTail": "来自哪里：a <b>智能插头 Home Assistant</b> (手机在自己的充电器 ) , 或两个 <b>快捷键</b>例如 <code>uhubctl</code> 为一 USB 带有可切换端口的集线器。 USB 电源面板不断运行过 Wi-Fi.",
      "s.claude.hint": "何时 Claude Code 请求权限(运行命令,编辑文件 ) , 手机显示请求 <b>允许</b> 以及 <b>否定</b>. 如果电话未连接或没有人及时回答, Claude Code 这个需要一个小的钩子,在终端中问 <code>~/.claude/settings.json</code>; PhoneBox 为您添加它(备份保存在文件旁边 ) 。",
      "s.wifi.lead": "通过一次插入来配对手机 USB 打开后(并重新启动 ) , 或没有电缆: <b>将手机与 Wi-Fi</b> 显示一个 QR 手机然后通过 HTTPS 与此 PC 对话,仅信任此 PC 的证书并且必须提供秘密密钥。 手机和此 PC 必须在同一网络上 &mdash; 或两者都在同一网 <a href=\"https://tailscale.com\" target=\"_blank\" rel=\"noopener\">Tailscale</a>,它也从另一个地方或跨分开的工作 Wi-Fi 网络。 Windows 防火墙会询问一次 &mdash; 允许它(勾选网络类型 Tailscale 还有,也不要太过分。",
